{"query": "
SELECT table_schema, table_name 
FROM information_schema.tables 
WHERE table_schema NOT IN ('pg_catalog', 'information_schema', 'public')
ORDER BY table_schema, table_name;
"}

{"query": "
SELECT table_name, column_name, data_type, is_nullable
FROM information_schema.columns
WHERE table_schema = 'employees'
ORDER BY table_name, ordinal_position;
"}

{"query": "
-- Drop if exists and recreate employee_retention_analysis
DROP TABLE IF EXISTS employees.employee_retention_analysis;

CREATE TABLE employees.employee_retention_analysis (
    department_name VARCHAR(100) NOT NULL,
    total_employees_ever INTEGER NOT NULL,
    current_employees INTEGER NOT NULL,
    former_employees INTEGER NOT NULL,
    retention_rate DECIMAL(6,2) NOT NULL
);
"}

{"query": "
-- Drop if exists and recreate high_risk_employees
DROP TABLE IF EXISTS employees.high_risk_employees;

CREATE TABLE employees.high_risk_employees (
    employee_id BIGINT NOT NULL,
    full_name VARCHAR(100) NOT NULL,
    current_department VARCHAR(100) NOT NULL,
    tenure_days INTEGER NOT NULL,
    current_salary INTEGER NOT NULL,
    risk_category VARCHAR(20) NOT NULL
);
"}

{"query": "
-- Drop if exists and recreate turnover_trend_analysis
DROP TABLE IF EXISTS employees.turnover_trend_analysis;

CREATE TABLE employees.turnover_trend_analysis (
    departure_year INTEGER NOT NULL,
    departures_count INTEGER NOT NULL,
    avg_tenure_days DECIMAL(10,2) NOT NULL,
    avg_final_salary DECIMAL(12,2) NOT NULL
);
"}

{"query": "
-- What's the max from_date for active salary records (to_date = '9999-01-01')?
-- This helps identify the "current" date context in the dataset
SELECT MAX(from_date) as latest_active_salary_start, MIN(from_date) as earliest_active_salary_start
FROM employees.salary WHERE to_date = '9999-01-01';
"}
